#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int dcount = 0, xcount = 0;
    for (int i = 0; i < n; i++) {
        int d, x;
        scanf("%d %d", &d, &x);
        int diff = (d - x) % 5;
        if (diff < 0) diff += 5;
        if (diff == 1 || diff == 2) dcount++;
        else xcount++;
    }
    if (dcount > xcount) printf("dario\n");
    else printf("xerxes\n");
    return 0;
}
